def is_multiply_prime(a):
    """Function to check if the given number is the multiplication of 3 prime numbers."""
    if a < 2:
        return False

    prime_factors = []

    # Check for smallest prime factor 2
    while a % 2 == 0:
        prime_factors.append(2)
        a //= 2

    # Check for odd prime factors
    for i in range(3, int(math.sqrt(a)) + 1, 2):
        while a % i == 0:
            prime_factors.append(i)
            a //= i

    # If a is still greater than 2, it must be a prime number
    if a > 2:
        prime_factors.append(a)

    # Check if there are exactly 3 prime factors
    return len(prime_factors) == 3 and all(is_prime(factor) for factor in prime_factors)

