from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(x, y, path):
        nonlocal min_path
        if len(path) == k:
            if not min_path or path < min_path:
                min_path = path.copy()
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                dfs(nx, ny, path + [grid[nx][ny]])

    min_path = None
    for i in range(n):
        for j in range(n):
            dfs(i, j, [grid[i][j]])

    return min_path

