assert find_Rotations("ab") == 2
assert find_Rotations("abc") == 3

def max_difference(test_list):
    # Calculate the absolute difference for each pair and store it in a new list
    res = [abs(b - a) for a, b in test_list]
    # Return the maximum value from the list of differences
    return max(res)

def subject_marks(marks):
    # Sort the list of tuples based on the second item in each tuple
    return sorted(marks, key=lambda x: x[1])

def bell_number(n): 
    # Initialize a list to store Bell numbers up to n
    B = [0] * (n + 1) 
    B[0] = 1  # Base case: Bell number for 0 is 1

    # Compute Bell numbers using dynamic programming
    for i in range(1, n + 1): 
        B[i] = 0
        for j in range(i - 1, -1, -1): 
            B[j] += B[j - 1] if j > 0 else 1

    return B[n]

