assert sequence(10) == 6
assert sequence(2) == 1
assert sequence(3) == 2

def merge_dictionaries_three(dict1, dict2, dict3):
    # Create a new dictionary and update it with the contents of the three input dictionaries
    merged_dict = {}
    merged_dict.update(dict1)
    merged_dict.update(dict2)
    merged_dict.update(dict3)

    return merged_dict

