from collections import ChainMap

def merge_dictionaries_three(dict1, dict2, dict3):
    # Use ChainMap to combine the dictionaries and then convert it back to a dictionary
    combined_view = ChainMap(dict1, dict2, dict3)
    merged_dict = dict(combined_view)

    return merged_dict

