def closest_num(n):
    # Subtract 1 from the given number to get the closest smaller number
    return (n - 1)

def power(a, b):
    # Base case: any number to the power of 0 is 1
    if (b == 0):
        return 1
    # Base case: 0 to the power of any positive number is 0
    elif (a == 0):
        return 0
    # Base case: any number to the power of 1 is itself
    elif (b == 1):
        return a
    # Recursive case: multiply 'a' by the result of 'a' raised to the power of 'b-1'
    else:
        return (a * power(a, b - 1))

# Test cases
assert power(3, 4) == 81
assert power(2, 3) == 8
assert power(5, 5) == 3125

def eulerian_num(n, m):
    # Base case: If n is equal to m or m is 0, return 1
    if n == m or m == 0:
        return 1

    # Recursive relation for Eulerian numbers
    return ((n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m))

# Test cases
assert eulerian_num(3, 1) == 4
assert eulerian_num(4, 1) == 11
assert eulerian_num(5, 3) == 26

def check_integer(s):
    # Check if the string is empty
    if len(s) == 0:
        return False

    # Check if all characters in the string are digits
    for i in range(len(s)):
        if s[i] < '0' or s[i] > '9':
            return False

    return True

