def amicable_numbers_sum(n):
    # Helper function to calculate the sum of proper divisors of a number
    def sum_of_divisors(x):
        return sum([i for i in range(1, x) if x % i == 0])

    # Initialize a list to store amicable pairs
    amicable_pairs = []

    # Iterate through numbers from 1 to n-1
    for num in range(1, n):
        # Calculate the sum of divisors of the current number
        sum_divs = sum_of_divisors(num)

        # Check if the sum of divisors is within the range and forms an amicable pair
        if sum_divs > num and sum_of_divisors(sum_divs) == num:
            amicable_pairs.append((num, sum_divs))

    # Return the sum of all unique amicable numbers
    return sum(set(num for pair in amicable_pairs for num in pair))

# Test cases
assert amicable_numbers_sum(999) == 504
assert amicable_numbers_sum(9999) == 31626
assert amicable_numbers_sum(99) == 0

def amicable_numbers_sum(n):
    # Helper function to calculate the sum of proper divisors of a number
    def sum_of_divisors(x):
        return sum([i for i in range(1, x // 2 + 1) if x % i == 0])

    # Initialize a set to store amicable numbers
    amicable_numbers = set()

    # Iterate through numbers from 1 to n-1
    for num in range(1, n):
        # Calculate the sum of divisors of the current number
        sum_divs = sum_of_divisors(num)

        # Check if the sum of divisors is within the range and forms an amicable pair
        if sum_divs > num and sum_of_divisors(sum_divs) == num:
            amicable_numbers.add(num)
            amicable_numbers.add(sum_divs)

    # Return the sum of all unique amicable numbers
    return sum(amicable_numbers)

# Test cases
assert amicable_numbers_sum(999) == 504
assert amicable_numbers_sum(9999) == 31626
assert amicable_numbers_sum(99) == 0

def magic_square_test(matrix): 
    n = len(matrix) 
    s = 0

    # Calculate the sum of the first row for reference
    for i in range(0, n): 
        s += matrix[0][i] 

    # Check sums of all rows
    for i in range(1, n): 
        s2 = 0
        for j in range(n): 
            s2 += matrix[i][j] 
        if s2 != s: 
            return False

    # Check sums of all columns
    for i in range(n): 
        s2 = 0
        for j in range(n): 
            s2 += matrix[j][i] 
        if s2 != s: 
            return False

    # Check sum of main diagonal
    s2 = 0
    for i in range(n): 
        s2 += matrix[i][i] 
    if s2 != s: 
        return False

    # Check sum of secondary diagonal
    s2 = 0
    for i in range(n): 
        s2 += matrix[i][n - 1 - i] 
    if s2 != s: 
        return False

    return True

