def is_majority(arr, n, x):
    # Find the first occurrence of x in arr[]
    i = find_first(arr, 0, n - 1, x)

    # If x is not present at all, return false
    if i == -1:
        return False

    # Check if x is the majority element
    if ((i + n // 2) < n and arr[i + n // 2] == x):
        return True
    else:
        return False

# Helper function to perform binary search for the first occurrence of x
def find_first(arr, low, high, x):
    while (high >= low):
        mid = (low + high) // 2

        # Check if x is present at mid
        if (mid == 0 or x > arr[mid - 1]) and (arr[mid] == x):
            return mid
        elif (x > arr[mid]):
            low = mid + 1
        else:
            high = mid - 1

    return -1

