def get_total_number_of_sequences(m, n):
    # Initialize a 2D list with zeros
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Iterate over all possible values of m and sequence lengths
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # If the sequence length is 1, there's only one possibility (the value itself)
            if j == 1:
                dp[i][j] = i
            else:
                # Calculate the number of sequences by summing up the possibilities from half to the current value
                dp[i][j] = sum(dp[k][j - 1] for k in range(i // 2, i + 1))

    # Return the total number of sequences of length n with elements up to m
    return dp[m][n]

def max_sum(arr):
    n = len(arr)

    # Initialize two arrays to store the maximum sum of increasing and decreasing subsequences
    inc = [0] * n
    dec = [0] * n

    # Fill inc[] such that inc[i] contains the maximum sum of increasing subsequence ending with arr[i]
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Fill dec[] such that dec[i] contains the maximum sum of decreasing subsequence starting with arr[i]
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence by adding inc[i] and dec[i] and subtracting arr[i] (to avoid double counting)
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

