def lps(s):
    n = len(s)

    # Create a 2D array to store lengths of longest palindromic subsequences.
    L = [[0 for x in range(n)] for y in range(n)]

    # Strings of length 1 are palindrome of length 1
    for i in range(n):
        L[i][i] = 1

    # Build the table. Note that the lower diagonal values of table are useless and not filled in the process.
    for cl in range(2, n + 1):  # cl is length of substring
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                L[i][j] = 2
            elif s[i] == s[j]:
                L[i][j] = L[i + 1][j - 1] + 2
            else:
                L[i][j] = max(L[i][j - 1], L[i + 1][j])

    # length of the longest palindromic subsequnce
    return L[0][n - 1]

