    # Initialize a list to keep track of prime status for each number up to n-1
    prime = [True] * (n - 1)

    # Iterate over each number starting from 2 to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        # If the current number is still marked as prime
        if prime[i - 2]:
            # Mark all multiples of this number as not prime
            for j in range(i * i, n, i):
                prime[j - 2] = False

    # Count and return the number of primes found
    return sum(prime)

