def newman_prime(n):
    # Initialize the list of Newman-Shanks-Williams primes with the first two known values
    primes = [2, 3]

    # Function to check if a number is prime
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Generate Newman-Shanks-Williams numbers and check for primality
    while len(primes) < n:
        next_num = sum(primes[-i] * primes[-i - 1] for i in range(len(primes))) + 1
        if is_prime(next_num):
            primes.append(next_num)

    # Return the nth Newman-Shanks-Williams prime
    return primes[n - 1]

