def max_aggregate(test_list):
    # Initialize an empty dictionary to store the sum of values for each key
    res_dict = {}

    # Iterate through each tuple in the list
    for key, val in test_list:
        # If the key is already in the dictionary, add the value to its current sum
        if key in res_dict:
            res_dict[key] += val
        else:
            # Otherwise, initialize the key with the current value
            res_dict[key] = val

    # Find the key with the maximum sum and return it along with the sum
    res = max(res_dict.items(), key=lambda ele: ele[1])
    return res

import math

def count_binary_seq(n):
    # Initialize a list to store binomial coefficients
    C = [0] * (2 * n + 1)

    # Base case: C[0] is always 1
    C[0] = 1

    # Calculate binomial coefficients using Pascal's triangle
    for i in range(1, 2 * n + 1):
        C[i] = 0
        for j in range(min(i, n), -1, -1):
            if j == 0:
                C[j] = 1
            else:
                C[j] += C[j - 1]

    # Calculate the number of valid binary sequences
    res = 0
    for i in range(n + 1):
        res += C[i] ** 2

    return res

