def first_non_repeating_character(s):
    # Create an empty dictionary to store character counts
    char_count = {}

    # Iterate over each character in the string
    for char in s:
        if char in char_count:
            # If character is already in dictionary, increment its count
            char_count[char] += 1
        else:
            # If character is not in dictionary, add it with count 1
            char_count[char] = 1

    # Iterate over each character in the string again
    for char in s:
        # Check if the count of the character is 1
        if char_count[char] == 1:
            # Return the first non-repeating character
            return char

    # If no non-repeating character is found, return None
    return None

# Test cases
assert first_non_repeating_character("abcabc") == None
assert first_non_repeating_character("abc") == "a"
assert first_non_repeating_character("ababc") == "c"

def median_numbers(x, y, z):
    # Sort the numbers and return the middle one as the median
    if (y < x < z) or (z < x < y):
        return float(x)
    elif (x < y < z) or (z < y < x):
        return float(y)
    else:
        return float(z)

# Test cases
assert median_numbers(25, 55, 65) == 55.0
assert median_numbers(20, 10, 30) == 20.0
assert median_numbers(15, 45, 75) == 45.0

def sum_of_digits(nums):
    # Initialize the total sum to zero
    total_sum = 0

    # Helper function to calculate the sum of digits of a single number
    def sum_digits(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Iterate through each element in the list
    for item in nums:
        # If the item is a list, recursively call sum_of_digits on it
        if isinstance(item, list):
            total_sum += sum_of_digits(item)
        # If the item is an integer, add its sum of digits to the total sum
        elif isinstance(item, int):
            total_sum += sum_digits(item)

    # Return the computed total sum
    return total_sum

