def max_Product(arr):
    # Check if the array has less than two elements
    if len(arr) < 2:
        return None

    # Initialize variables to store the maximum and minimum products
    max_product = float('-inf')
    min_product = float('inf')

    # Initialize variables to store the maximum and second maximum numbers
    max_num = float('-inf')
    sec_max_num = float('-inf')

    # Initialize variables to store the minimum and second minimum numbers
    min_num = float('inf')
    sec_min_num = float('inf')

    # Iterate through each number in the array
    for num in arr:
        # Update the maximum and minimum products
        if num > 0:
            if num * max_product > max_product:
                max_product *= num
            if num * min_product < min_product:
                min_product *= num
        elif num < 0:
            if num * max_product < max_product:
                max_product *= num
            if num * min_product > min_product:
                min_product *= num

        # Update the maximum and second maximum numbers
        if num > max_num:
            sec_max_num = max_num
            max_num = num
        elif num > sec_max_num:
            sec_max_num = num

        # Update the minimum and second minimum numbers
        if num < min_num:
            sec_min_num = min_num
            min_num = num
        elif num < sec_min_num:
            sec_min_num = num

    # Return the pair with the highest product
    return (max_num, sec_max_num)

# Test cases
