def extract_even(test_tup):
    # Define a recursive function to filter even numbers
    def filter_even(sub_tup):
        res = []
        for ele in sub_tup:
            if isinstance(ele, tuple):
                # Recursively filter even numbers in nested tuples
                res.append(filter_even(ele))
            elif ele % 2 == 0:
                # Append even numbers directly
                res.append(ele)
        return tuple(res)

    # Apply the recursive function to the input tuple
    result = filter_even(test_tup)
    return result

