    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            k -= 1
            if k == 0:
                return arr1[i]
            i += 1
        else:
            k -= 1
            if k == 0:
                return arr2[j]
            j += 1

    # If we have exhausted all elements in arr1, return the k-th element from arr2
    while j < len(arr2):
        k -= 1
        if k == 0:
            return arr2[j]
        j += 1

    # If we have exhausted all elements in arr2, return the k-th element from arr1
    while i < len(arr1):
        k -= 1
        if k == 0:
            return arr1[i]
        i += 1

