def move_num(s):
    # Extract digits and non-digits using list comprehensions
    num = [i for i in s if i.isdigit()]
    alpha = [i for i in s if not i.isdigit()]

    # Join the non-digit characters and then append the digit characters
    return ''.join(alpha) + ''.join(num)

def get_median(arr1, arr2, n):
    # Concatenate the two arrays and sort them
    merged_arr = sorted(arr1 + arr2)

    # Calculate the median based on the length of the merged array
    if n % 2 != 0:
        return float(merged_arr[n // 2])
    else:
        return (float(merged_arr[(n - 1) // 2]) + float(merged_arr[n // 2])) / 2

