    freq = {}

    # Iterate through the list and count the frequency of each element
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the sum of non-repeated elements
    sum_non_repeated = 0

    # Iterate through the dictionary and add the value to the sum if its frequency is 1
    for key, value in freq.items():
        if value == 1:
            sum_non_repeated += key

    return sum_non_repeated

