def is_woodall(x):
    if not isinstance(x, int):
        return False
    if x <= 0 or x % 2 == 0:
        return False
    if x == 1:
        return True

    # Check if x can be written as 2^n * n - 1
    n = 1
    while True:
        woodall_number = 2**n * n - 1
        if woodall_number > x:
            break
        if woodall_number == x:
            return True
        n += 1

    return False

