def is_sublist(main_list, sub_list):
    # 如果子列表为空，则认为是主列表的子列表
    if not sub_list:
        return True
    # 如果子列表长度大于主列表长度，则不可能是子列表
    elif len(sub_list) > len(main_list):
        return False
    else:
        # 遍历主列表，检查是否存在与子列表相等的连续子序列
        for i in range(len(main_list) - len(sub_list) + 1):
            if main_list[i:i + len(sub_list)] == sub_list:
                return True
        return False

