def div_sum(num):
    res = 1
    i = 2
    while i * i <= num:
        if num % i == 0:
            res += i
            if i * i != num:
                res += num // i
        i += 1
    return res

def amicable_numbers_sum(limit):
    amicables = set()
    for num in range(2, limit + 1):  # 修改起始值为 2
        if num in amicables:
            continue
        sum_fact = div_sum(num)
        sum_fact2 = div_sum(sum_fact)
        if num == sum_fact2 and num != sum_fact:
            amicables.add(num)
            amicables.add(sum_fact2)
    return sum(amicables)

def magic_square_test(my_matrix):
    n = len(my_matrix)
    s = sum(my_matrix[0])

    # Check rows and columns
    for i in range(n):
        if sum(my_matrix[i]) != s or sum(my_matrix[j][i] for j in range(n)) != s:
            return False

    # Check diagonals
    if sum(my_matrix[i][i] for i in range(n)) != s or sum(my_matrix[i][n - i - 1] for i in range(n)) != s:
        return False

    return True

