def max_sum(arr):
    n = len(arr)

    # Calculate MSIS values from left to right
    MSIS = [arr[i] for i in range(n)]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and MSIS[i] < MSIS[j] + arr[i]:
                MSIS[i] = MSIS[j] + arr[i]

    # Calculate MSDS values from right to left
    MSDS = [arr[i] for i in range(n)]
    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and MSDS[i] < MSDS[j] + arr[i]:
                MSDS[i] = MSDS[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum = float('-inf')
    for i in range(n):
        max_sum = max(max_sum, MSIS[i] + MSDS[i] - arr[i])

    return max_sum

