def validate(n):
    # 将整数转换为字符串并拆分为单个字符
    digits = [int(digit) for digit in str(n)]

    # 使用字典来跟踪每个数字的频率
    frequency = {}

    # 计算每个数字的频率
    for digit in digits:
        if digit in frequency:
            frequency[digit] += 1
        else:
            frequency[digit] = 1

    # 检查每个数字的频率是否小于或等于该数字本身
    for digit, freq in frequency.items():
        if freq > digit:
            return False

    return True

