def max_sum_increasing_subseq(arr, n, index, k):
    # Initialize the DP table with zeros
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Fill the first row of the DP table
    for i in range(n):
        if arr[i] >= arr[0]:
            dp[0][i] = arr[i] + arr[0]
        else:
            dp[0][i] = arr[i]

    # Fill the rest of the DP table
    for i in range(1, n):
        for j in range(n):
            if arr[j] > arr[i] and j > i:
                if dp[i - 1][i] + arr[j] > dp[i - 1][j]:
                    dp[i][j] = dp[i - 1][i] + arr[j]
                else:
                    dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    # Return the value at the specified index and k
    return dp[index][k]

