def set_left_most_unset_bit(n):
    # 如果 n 是 0 或者 n 的二进制表示中所有位都是 1，则直接返回 n
    if not n or n & (n + 1) == 0:
        return n

    pos, temp, count = 0, n, 1

    # 遍历 n 的每一位，找到最左边的未设置位
    while temp:
        if not temp & 1:
            pos = count
        count += 1
        temp >>= 1

    # 将最左边的未设置位设置为 1
    return n | 1 << pos

def find_lucas(n):
    # Base cases for the first two Lucas numbers
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        # Recursive case to calculate the nth Lucas number
        return find_lucas(n - 1) + find_lucas(n - 2)

