def sumofFactors(n):
    # 初始化结果为 0
    result = 0

    # 遍历从 1 到 n 的所有数字
    for i in range(1, n + 1):
        # 检查 i 是否是偶数且能整除 n
        if n % i == 0 and i % 2 == 0:
