assert is_Sub_Array([1,2,1],[1,2,1]) == True
assert is_Sub_Array([1,0,2,2],[2,2,0]) == False

def is_Sub_Array(A, B):
    if len(B) == 0:
        return True
    if len(B) > len(A):
        return False

    for i in range(len(A) - len(B) + 1):
        j = 0
        while j < len(B) and A[i + j] == B[j]:
            j += 1
        if j == len(B):
            return True
    return False

