def last_Digit_Factorial(n): 
    # 如果 n 小于 5，则直接计算阶乘并返回最后一位数字
    if n < 5: 
        mul = 1
        for i in range(1, n + 1): 
            mul *= i 
        return mul % 10

    # 对于 n 大于等于 5，如果 n 是 5 或其倍数，则最后一位数字为 0
    if n % 5 == 0: 
        return 0

    # 否则，返回 2 的 (n-1) 次方的最后一位数字
    mul = 2
    for i in range(2, n): 
        mul = (mul * (i % 10)) % 10

    return mul

