def find_first_occurrence(A, x):
    left, right = (0, len(A) - 1)
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if x == A[mid]:
            result = mid
            right = mid - 1  # 继续向左搜索
        elif x < A[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return result

def tuple_to_dict(test_tup):
