def get_pairs_count(arr, sum_):
    cnt = 0
    seen = {}

    for n in arr:
        complement = sum_ - n
        if complement in seen:
            cnt += seen[complement]
        if n in seen:
            seen[n] += 1
        else:
            seen[n] = 1

    return cnt

