assert get_pairs_count([1, 5, 7, -1, 5], 6) == 3
assert get_pairs_count([1, -2, 3], 1) == 1

def odd_num_sum(n):
    sm = 0
    for i in range(1, n + 1):
        j = 2 * i - 1
        sm += j ** 4
    return sm

from collections import deque

def check_expression(expression):
    # Check if the length of the expression is even
    if len(expression) % 2 != 0:
        return False

    # Initialize an empty stack
    stack = deque()

    # Dictionary to hold matching pairs of parentheses
    matching_pairs = {')': '(', '}': '{', ']': '['}

    # Iterate through each character in the expression
    for char in expression:
        # If the character is an opening parenthesis, push it onto the stack
        if char in matching_pairs.values():
            stack.append(char)
        # If the character is a closing parenthesis
        elif char in matching_pairs:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening parenthesis, return False
            if not stack or stack.pop() != matching_pairs[char]:
                return False

    # If the stack is empty, all parentheses are matched; otherwise, return False
    return not stack

