import re

def occurance_substring(text, pattern):
    matches = list(re.finditer(pattern, text))
    if not matches:
        return None
    match = matches[0]
    s = match.start()
    e = match.end()
    return (text[s:e], s, e)

import math

def count_divisors(n):
    cnt = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if n // i != i:
                cnt += 2
            else:
                cnt += 1
    return cnt % 2 == 0

