def test_three_equal(x, y, z):
    # 使用集合来判断是否有重复元素
    result = set([x, y, z])
    # 如果集合长度为1，说明所有元素都相等
    if len(result) == 1:
        return 3
    # 如果集合长度为2，说明有两个不同的元素
    elif len(result) == 2:
        return 2
    # 如果集合长度为3，说明三个元素都不相等
    else:
        return 0

